using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
namespace PlatinumPrivateLauncher;
sealed partial class Launcher
{
    DataGridView controlsGrid=null!;
    ControlBindings? bindingDocument;
    string bindingPath="";
    readonly Label bindingStatus=new(){AutoSize=true,MaximumSize=new(820,0)};
    void ControlsPage(FlowLayoutPanel card)
    {
        bindingStatus.Text="Keyboard and controller buttons for your private game. Save changes while that game is closed.";bindingStatus.ForeColor=muted;card.Controls.Add(bindingStatus);
        controlsGrid=new(){Width=820,Height=340,ReadOnly=false,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,BackgroundColor=surface,BorderStyle=BorderStyle.None,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,EnableHeadersVisualStyles=false,ColumnHeadersHeight=38,RowTemplate={Height=32},DefaultCellStyle=new(){BackColor=surface,ForeColor=Color.White,SelectionBackColor=Color.FromArgb(34,64,75),SelectionForeColor=Color.White},ColumnHeadersDefaultCellStyle=new(){BackColor=Color.FromArgb(32,47,61),ForeColor=Color.White}};
        controlsGrid.Columns.Add(new DataGridViewTextBoxColumn{Name="action",HeaderText="ACTION",ReadOnly=true,FillWeight=140});controlsGrid.Columns.Add(new DataGridViewTextBoxColumn{Name="key",HeaderText="KEYBOARD",ReadOnly=true});
        var buttons=new List<PadChoice>();for(int i=0;i<32;i++)buttons.Add(new("Button "+i,i));foreach(var (label,value) in new[]{("D-pad up",65537),("D-pad down",65540),("D-pad left",65544),("D-pad right",65538)})buttons.Add(new(label,value));
        controlsGrid.Columns.Add(new DataGridViewComboBoxColumn{Name="pad",HeaderText="CONTROLLER",DisplayMember="Label",ValueMember="Value",DataSource=buttons,FlatStyle=FlatStyle.Flat});controlsGrid.DataError+=(_,e)=>{e.ThrowException=false;};controlsGrid.CellDoubleClick+=(_,e)=>{if(e.RowIndex>=0&&e.ColumnIndex==1)CaptureBinding();};var toolbar=new FlowLayoutPanel{Width=820,Height=56,WrapContents=false,Margin=new(0,8,0,10)};card.Controls.Add(toolbar);
        void Tool(string title,Func<Task> action){Add(toolbar,title,action);var button=actions[^1];button.AutoSize=false;button.MinimumSize=new(185,42);button.Size=new(190,42);button.Margin=new(0,4,10,4);}
        Tool("Load bindings",()=>{LoadBindings();return Task.CompletedTask;});Tool("Change selected key",()=>{CaptureBinding();return Task.CompletedTask;});Tool("Save bindings",SaveBindings);Tool("Restore defaults",()=>{bindingDocument??=new([]);FillBindings(true);bindingStatus.Text="Defaults staged. Save bindings to apply them.";return Task.CompletedTask;});card.Controls.Add(controlsGrid);
        card.Controls.Add(new Label{Text="Select an action, then Change selected keyboard key. Double-click a keyboard cell as a shortcut. Controller numbers are the game's SDL button indices; D-pad entries use its native hat values. These settings apply on the next private-game launch.",Width=820,Height=90,ForeColor=muted});
    }
    void LoadBindings(){bindingPath=Path.Combine(GameDir,"sim_config.ini");bindingDocument=new(File.Exists(bindingPath)?File.ReadAllBytes(bindingPath):[]);FillBindings(false);bindingStatus.Text=File.Exists(bindingPath)?"Loaded the private game's current bindings.":"Default bindings ready. Prepare your private game before saving.";}
    void FillBindings(bool defaults){controlsGrid.Rows.Clear();foreach(var a in ControlBindings.Actions){int key=defaults?a.Default:bindingDocument!.Values[a.Key+"Key"];int? joy=a.Joy==null?null:defaults?a.Joy:bindingDocument!.Values[a.Key+"JoyKey"];int i=controlsGrid.Rows.Add(new object[]{a.Label,KeyLabel(key),(object?)joy??DBNull.Value});controlsGrid.Rows[i].Tag=key;if(joy==null)controlsGrid.Rows[i].Cells[2].ReadOnly=true;else{var cell=(DataGridViewComboBoxCell)controlsGrid.Rows[i].Cells[2];if(!((List<PadChoice>)cell.DataSource!).Any(x=>x.Value==joy)){var choices=new List<PadChoice>((List<PadChoice>)cell.DataSource!){new("Custom "+joy,joy.Value)};cell.DataSource=choices;}}}}
    static string KeyLabel(int value){if(value is >=97 and <=122)return ((char)(value-32)).ToString();if(value is >=32 and <=126)return ((char)value).ToString();foreach(Keys key in Enum.GetValues<Keys>()){try{if(ControlBindings.FromWindowsKey(key)==value)return key switch{Keys.Return=>"Enter",Keys.ShiftKey=>"Left Shift",Keys.ControlKey=>"Left Ctrl",Keys.Menu=>"Left Alt",Keys.RShiftKey=>"Right Shift",Keys.RControlKey=>"Right Ctrl",Keys.RMenu=>"Right Alt",_=>key.ToString()};}catch(IOException){}}return "SDL "+value;}
    void CaptureBinding(){if(controlsGrid.CurrentCell==null)return;int row=controlsGrid.CurrentCell.RowIndex;using var dialog=new CaptureKey(ControlBindings.Actions[row].Label);if(dialog.ShowDialog(this)==DialogResult.OK){controlsGrid.Rows[row].Tag=dialog.Value;controlsGrid.Rows[row].Cells[1].Value=KeyLabel(dialog.Value);bindingStatus.Text="Binding staged. Save bindings to apply it.";}}
    async Task SaveBindings(){if(GameRunning())throw new Exception("Close the private game before saving bindings.");if(!File.Exists(Path.Combine(GameDir,"Platinum.exe")))throw new Exception("Prepare the private game in Game setup first.");if(bindingDocument==null)throw new Exception("Load the current bindings first.");controlsGrid.EndEdit();var edits=new Dictionary<string,int>();for(int i=0;i<ControlBindings.Actions.Length;i++){var a=ControlBindings.Actions[i];edits[a.Key+"Key"]=(int)controlsGrid.Rows[i].Tag!;if(a.Joy!=null)edits[a.Key+"JoyKey"]=Convert.ToInt32(controlsGrid.Rows[i].Cells[2].Value);}
        var shared=edits.Where(x=>x.Key.EndsWith("Key")&&!x.Key.EndsWith("JoyKey")).GroupBy(x=>x.Value).Where(g=>g.Count()>1).ToArray();if(shared.Length>0&&MessageBox.Show(this,"Some actions share a keyboard key. Keep those shared bindings?","Shared keys",MessageBoxButtons.YesNo,MessageBoxIcon.Information)!=DialogResult.Yes)return;
        var current=File.Exists(bindingPath)?await File.ReadAllBytesAsync(bindingPath):[];if(!current.SequenceEqual(bindingDocument.Original))throw new Exception("The game settings changed since loading. Load current bindings again.");var edited=bindingDocument.Build(edits);var check=new ControlBindings(edited);if(edits.Any(x=>check.Values[x.Key]!=x.Value))throw new Exception("The saved bindings did not validate.");
        Directory.CreateDirectory(GameDir);var backup=Path.Combine(Client,"SettingsBackups",DateTime.Now.ToString("yyyyMMdd-HHmmss-fffffff"));Directory.CreateDirectory(backup);await File.WriteAllBytesAsync(Path.Combine(backup,"sim_config.ini"),current);await File.WriteAllTextAsync(Path.Combine(backup,"bindings.json"),JsonSerializer.Serialize(edits));var temporary=bindingPath+".bindings.tmp";await File.WriteAllBytesAsync(temporary,edited);if(GameRunning()||!(File.Exists(bindingPath)?await File.ReadAllBytesAsync(bindingPath):[]).SequenceEqual(current))throw new Exception("Game/settings changed during saving; the original was kept.");File.Move(temporary,bindingPath,true);LoadBindings();bindingStatus.Text="Bindings saved. They will apply when you next launch the private game.";Log("Keyboard/controller bindings saved with a settings backup.");}
    sealed record PadChoice(string Label,int Value);
    sealed class CaptureKey:Form {internal int Value;readonly Label label=new(){Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter};internal CaptureKey(string action){Text="Bind "+action;ClientSize=new(470,180);StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(17,29,42);ForeColor=Color.White;Font=new("Segoe UI",13);KeyPreview=true;label.Text="Press the key for\n"+action;Controls.Add(label);var cancel=new Button{Text="Cancel",Dock=DockStyle.Bottom,Height=40};cancel.Click+=(_,_)=>{DialogResult=DialogResult.Cancel;Close();};Controls.Add(cancel);}void CapturePressedKey(Keys key,long bits){int scan=(int)((bits>>16)&255);bool extended=(bits&(1L<<24))!=0;key&=Keys.KeyCode;if(key==Keys.ShiftKey)key=scan==54?Keys.RShiftKey:Keys.LShiftKey;if(key==Keys.ControlKey)key=extended?Keys.RControlKey:Keys.LControlKey;if(key==Keys.Menu)key=extended?Keys.RMenu:Keys.LMenu;try{Value=ControlBindings.FromWindowsKey(key);DialogResult=DialogResult.OK;Close();}catch(IOException e){label.Text=e.Message;}}
        protected override bool ProcessKeyPreview(ref Message m){if(m.Msg is 0x100 or 0x104){CapturePressedKey((Keys)(int)m.WParam,m.LParam.ToInt64());return true;}return base.ProcessKeyPreview(ref m);}
        protected override bool ProcessCmdKey(ref Message m,Keys keyData){CapturePressedKey(keyData,m.LParam.ToInt64());return true;}
        protected override void OnKeyDown(KeyEventArgs e){CapturePressedKey(e.KeyCode,0);e.SuppressKeyPress=true;}}
}
